create table if not exists spiritual.planet_positions ( id bigint generated always as identity primary key, obs_date timestamptz not null, planet text not null check (planet in ('Sun', 'Moon', 'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune', 'Pluto')), longitude numeric(8,4), latitude numeric(8,4), distance_au numeric(12,6), magnitude numeric(6,2), phase numeric(5,2), constellation text, is_retrograde boolean default false, ra_hours numeric(6,3), dec_degrees numeric(8,4), source text default 'api', calculated_by uuid references identity.profiles (id), tenant_id uuid references core.tenants (id), created_at timestamptz default now(), unique (obs_date, planet) );
